const input = $input.first().json;
const dados = input.dados_roteador ? JSON.parse(input.dados_roteador) : {};

return [{
  json: {
    remotejid: input.remotejid,
    mensagem: input.mensagem,
    protocolo: input.protocolo || dados.dados_detectados?.protocolo || null,
    nome: input.nome || null,
    area: input.area || dados.intencao_detectada?.area || null,
    motivo_encaminhamento: dados.intencao_detectada?.motivo || 'Solicitação de atendimento humano'
  }
}];

