const raw = $input.first().json.output || $input.first().json.responder_cidadao || '';
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

try {
  const parsed = JSON.parse(cleaned);
  return [{ json: {
    responder_cidadao: parsed.responder_cidadao || cleaned,
    encaminhar_humano: true,
    area: $('Parsear Entrada').first().json.area || parsed.area || null,
    motivo: $('Parsear Entrada').first().json.motivo_encaminhamento
  } }];
} catch (e) {
  return [{ json: {
    responder_cidadao: cleaned || 'Vou transferir você para um atendente humano. Aguarde um momento, por favor.',
    encaminhar_humano: true,
    area: $('Parsear Entrada').first().json.area || null,
    motivo: $('Parsear Entrada').first().json.motivo_encaminhamento
  } }];
}
